import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/data/orders.db')
SECRET = os.environ.get('API_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # HMAC verification of JWT-like token (simplified)
        parts = token.rsplit('.', 1)
        if len(parts) != 2:
            return jsonify({'error': 'malformed token'}), 401
        payload, sig = parts
        expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/orders/search', methods=['GET'])
@require_auth
def search_orders():
    customer_id = request.args.get('customer_id', '')
    status = request.args.get('status', 'all')
    date_from = request.args.get('date_from', '')
    date_to = request.args.get('date_to', '')
    page = request.args.get('page', '1')
    page_size = request.args.get('page_size', '50')

    # Build base query
    conditions = []
    params = []

    if customer_id:
        conditions.append("customer_id = ?")
        params.append(customer_id)

    if status and status != 'all':
        # Validate status against known values
        valid_statuses = ['pending', 'shipped', 'delivered', 'cancelled', 'returned']
        if status not in valid_statuses:
            return jsonify({'error': 'invalid status'}), 400
        conditions.append("status = ?")
        params.append(status)

    if date_from:
        conditions.append("order_date >= ?")
        params.append(date_from)

    if date_to:
        conditions.append("order_date <= ?")
        params.append(date_to)

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    # Pagination - validated as integers
    try:
        p = int(page)
        ps = int(page_size)
        if ps > 200:
            ps = 200
        offset = (p - 1) * ps
    except ValueError:
        return jsonify({'error': 'invalid pagination'}), 400

    # Custom field selection - allows caller to specify columns
    fields = request.args.get('fields', 'order_id,customer_id,status,order_date,total')

    # Basic sanitization: only allow alphanumeric and underscores and commas
    if not all(c.isalnum() or c in ('_', ',', ' ') for c in fields):
        return jsonify({'error': 'invalid field specification'}), 400

    query = f"SELECT {fields} FROM orders WHERE {where_clause} ORDER BY order_date DESC LIMIT ? OFFSET ?"
    params.extend([ps, offset])

    db = get_db()
    try:
        rows = db.execute(query, params).fetchall()
        return jsonify({'orders': [dict(r) for r in rows], 'page': p, 'page_size': ps})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/orders/<order_id>/notes', methods=['POST'])
@require_auth
def add_note(order_id):
    data = request.get_json()
    if not data or 'note' not in data:
        return jsonify({'error': 'note required'}), 400
    db = get_db()
    db.execute("INSERT INTO order_notes (order_id, note, created_at) VALUES (?, ?, datetime('now'))",
               (order_id, data['note']))
    db.commit()
    return jsonify({'status': 'ok'}), 201

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
